import { WEBCAM_CHANNEL } from "@/data/webcams";
import type { SectionId } from "@/ia/sections";

/** "bundled": a dataset shipped with the app and regenerated by a script, not fetched per request. */
export type SourceState = "connected" | "bundled" | "planned" | "blocked";

export type SourceDef = {
  id: string;
  name: string;
  section: SectionId;
  owner: string;
  homepage: string;
  licence: string;
  /** How often the upstream actually changes, in plain words. */
  cadence: string;
  /** How long a fetched copy is reused, and how often an open page refreshes it, in seconds. */
  revalidate: number;
  /** Minutes after the observation time before the UI marks it stale. */
  staleAfter: number;
  state: SourceState;
  note?: string;
};

