export type SourceId = (typeof sources)[number]["id"];

export const sourceById = Object.fromEntries(sources.map((s) => [s.id, s])) as Record<SourceId, SourceDef>;

export const sourcesInSection = (section: SectionId): SourceDef[] => sources.filter((s) => s.section === section);
